import time


class Timer:
    def __init__(self, duration, callback=None, retries=None, owner=None):
        self.duration = duration
        self.callback = callback
        self.retries = retries
        self.owner = owner
        self.running = False
        self.start_time = None
        self.curr_retry = self.retries

    def start(self):
        self.start_time = time.time()
        self.running = True

    def stop(self):
        self.running = False

    def is_running(self):
        return self.running

    def run_callback(self):
        if self.callback:
            self.stop()
            if self.owner:
                self.callback(self.owner)
            else:
                self.callback()
            self.start()

    def check_expired(self):
        ret = False
        if self.running and (time.time() > self.start_time + self.duration):

            if self.retries is not None:
                if self.retries < 0:
                    self.run_callback()
                elif self.curr_retry > 0:
                    self.curr_retry -= 1
                    self.run_callback()
                else:
                    self.curr_retry = self.retries
                    ret = True
            else:
                self.run_callback()
                ret = True

            if ret:
                self.stop()
        return ret
